#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_tamil_translation() {
        assert_eq!(translate_key("Tamil", 50, false, false), Some("அ"));
        assert_eq!(translate_key("Tamil", 30, false, false), Some("ய"));
    }

    #[test]
    fn test_russian_translation() {
        assert_eq!(translate_key("Russian", 33, false, false), Some("а"));
    }

    #[test]
    fn test_greek_translation() {
        assert_eq!(translate_key("Greek", 30, false, false), Some("α"));
    }

    #[test]
    fn test_german_altgr() {
        assert_eq!(translate_key("German", 16, false, true), Some("@"));
    }

    #[test]
    fn test_us_intl_deadkeys() {
        assert_eq!(translate_key("US International", 40, false, false), Some("dead_acute"));
    }
}
